-- CommandProject optimize (generated by the launcher): frame limit at the start of each match.
-- sc_FrameTimeClamp = minimum time between frames in ms (the game's default is 10 = 100 FPS);
-- matches with more than 8 armies may use a lower limit, which leaves more CPU to the simulation.
CPOptFrameMs = {FRAME_MS}
CPOptBigFrameMs = {BIG_FRAME_MS}
function CPOptimizeStart()
    pcall(ConExecute, 'sc_FrameTimeClamp ' .. CPOptFrameMs)
    if CPOptBigFrameMs == CPOptFrameMs then return end
    ForkThread(function()
        -- the armies table appears a moment after the game UI starts
        for i = 1, 300 do
            local ok, t = pcall(GetArmiesTable)
            if ok and t and t.armiesTable then
                local n = 0
                for _, a in t.armiesTable do
                    if not a.civilian then n = n + 1 end
                end
                if n > 0 then
                    if n > 8 then pcall(ConExecute, 'sc_FrameTimeClamp ' .. CPOptBigFrameMs) end
                    return
                end
            end
            WaitSeconds(0.1)
        end
    end)
end
